{
  "metadata": {
    "run_id": "cw-ms-remote-0a1b2c3d",
    "review_date": "2026-10-24",
    "last_updated": "2026-10-24T22:17:06.920087+00:00"
  },
  "company_name": "Cadence",
  "slug": "cadence",
  "stage": "seed",
  "sector": "B2B SaaS",
  "geography": "US",
  "sector_type": "saas"
}

{
  "items": [
    {
      "id": "structural_tam_gt_sam_gt_som",
      "category": "Structural Checks",
      "label": "TAM > SAM > SOM",
      "status": "pass",
      "notes": "Both approaches maintain proper nesting. Top-down: TAM $567M > SAM $312M > SOM $9.4M. Bottom-up: TAM $579M > SAM $376M > SOM $9.4M."
    },
    {
      "id": "structural_definitions_correct",
      "category": "Structural Checks",
      "label": "Definitions used correctly",
      "status": "pass",
      "notes": "TAM represents the full HVAC/plumbing/electrical FSM software market (all businesses); SAM narrows to the SMB or serviceable segment Cadence can actually serve; SOM is the realistic 3-year capture. Definitions are applied consistently across both approaches."
    },
    {
      "id": "tam_matches_product_scope",
      "category": "TAM Scoping",
      "label": "TAM matches product scope",
      "status": "pass",
      "notes": "TAM is scoped to the US field service management software market for HVAC, plumbing, and electrical trades \u2014 the specific product category and geography Cadence targets. A broad US FSM market total was narrowed to these three trades using a vertical-share estimate, and the bottom-up TAM independently counts only employer establishments in those same NAICS codes."
    },
    {
      "id": "source_segments_match",
      "category": "TAM Scoping",
      "label": "Source segments match product segments",
      "status": "pass",
      "notes": "The US FSM market total sources (P&S Intelligence, IBISWorld) cover all FSM verticals, which is broader than the three target trades \u2014 this partial mismatch is explicitly flagged and handled by deriving a vertical share. Customer count data is sourced from Census Bureau NAICS codes 238220 and 238210, which map exactly to HVAC/plumbing and electrical contractors. ARPU data from Software Advice covers SMB field service SaaS, an exact segment match. Where sources are broader, the mismatch is noted and a narrowing step is applied."
    },
    {
      "id": "som_share_defensible",
      "category": "SOM Realism",
      "label": "SOM share is defensible",
      "status": "pass",
      "notes": "Top-down SOM uses 3% of SAM; bottom-up uses 2.5% of serviceable customers \u2014 both over a 3-year horizon. For a seed-stage vertical SaaS in a fragmented market with many smaller competitors, 2.5\u20133% of SAM in the first three years is within the defensible range (1\u20135%). The derivation also cross-references the implied customer count (~3,100 businesses at $3,000 ARPU \u2248 $9.4M ARR), which is a plausible milestone for a well-funded seed team."
    },
    {
      "id": "som_backed_by_gtm",
      "category": "SOM Realism",
      "label": "SOM backed by go-to-market plan",
      "status": "not_applicable",
      "notes": "Cadence's materials were provided as a text description only \u2014 no pitch deck or financial model was submitted. GTM evidence (customer acquisition strategy, funnel metrics, comparable-company benchmarks) can only be drawn from such materials. This item is skipped for want of materials and should be addressed before presenting to investors."
    },
    {
      "id": "som_consistent_with_projections",
      "category": "SOM Realism",
      "label": "SOM consistent with financial projections",
      "status": "not_applicable",
      "notes": "No financial model or document showing hiring plan, sales capacity, or burn rate was provided. Alignment between the SOM revenue figure and the business plan cannot be assessed from a text description alone. This item is skipped for want of materials and should be addressed before investor conversations."
    },
    {
      "id": "data_current",
      "category": "Data Quality",
      "label": "Data is current",
      "status": "pass",
      "notes": "The US FSM market size figures come from reports accessed in October 2026 (P&S Intelligence, IBISWorld). HVAC and plumbing employer counts use 2023 Census County Business Patterns data \u2014 within the 2-year window. The electrical contractor count references 2022 Census data via a secondary source, which is at the edge of the 2-year threshold; for a government count of a relatively stable sector this is acceptable, but sourcing the 2023 or 2024 Census figure directly would strengthen the claim."
    },
    {
      "id": "sources_reputable",
      "category": "Data Quality",
      "label": "Sources are reputable",
      "status": "pass",
      "notes": "Primary market-size figures come from P&S Intelligence and IBISWorld (established analyst firms). Customer counts trace to Census Bureau data (government). ARPU benchmarks come from Software Advice (business press). One source \u2014 a Fieldproxy company blog \u2014 is used for the FSM adoption rate (context only, not a direct sizing input) and as a single source for the SMB share narrowing step (55%); the latter is the weakest link in the source stack. The company blog source is flagged with low confidence."
    },
    {
      "id": "figures_triangulated",
      "category": "Data Quality",
      "label": "Key figures triangulated",
      "status": "fail",
      "notes": "The US FSM market total is corroborated by two analyst firms (P&S Intelligence and IBISWorld) \u2014 that figure is well-triangulated. However, ARPU ($3,000/year) rests on a single pricing comparison source (Software Advice), and the SMB share used to narrow SAM (55%) comes from a single company blog. Both are key inputs to the analysis. Sourcing ARPU from a second independent source (e.g., a competitor's S-1 or an analyst pricing benchmark) and the SMB share from an independent industry association or analyst report would materially strengthen credibility."
    },
    {
      "id": "unsupported_figures_flagged",
      "category": "Data Quality",
      "label": "Unsupported figures flagged",
      "status": "pass",
      "notes": "Agent estimates \u2014 the HVAC/plumbing/electrical vertical share (27%), the serviceable customer share (65%), the top-down market capture rate (3%), and the bottom-up target capture rate (2.5%) \u2014 are all explicitly labeled as estimates with stated reasoning. None is presented as a researched fact. The derivation notes explain the basis for each estimate."
    },
    {
      "id": "validated_used_precisely",
      "category": "Data Quality",
      "label": "Validated used precisely",
      "status": "pass",
      "notes": "Validation statuses are used correctly throughout. The US FSM market total is labeled validated (two analyst firm sources). ARPU and the SMB share are labeled partially supported (one source each). The derived industry total is labeled partially supported because one of its inputs (the 27% vertical share) is an agent estimate. No figure is claimed as validated without meeting the two-source bar."
    },
    {
      "id": "assumptions_categorized",
      "category": "Data Quality",
      "label": "Assumptions categorized",
      "status": "pass",
      "notes": "Every assumption carries an explicit category: sourced (with citation), derived (with formula and factor list), or agent estimate (with stated reasoning). There are no unlabeled assumptions. The four agent estimates are individually identified and will be stress-tested in the sensitivity analysis."
    },
    {
      "id": "both_approaches_used",
      "category": "Methodology",
      "label": "Both approaches used",
      "status": "pass",
      "notes": "Both top-down (US FSM market total narrowed to the three target trades and SMB segment) and bottom-up (Census employer establishment count multiplied by ARPU, then narrowed by serviceable and target shares) approaches were completed. TAM, SAM, and SOM are calculated for each."
    },
    {
      "id": "approaches_reconciled",
      "category": "Methodology",
      "label": "Gap between the two approaches is explained",
      "status": "fail",
      "notes": "The TAM estimates from the two approaches differ by only 2.1% and the SOM estimates by 0.6%, but the SAM estimates differ by 18.8% ($312M top-down vs. $376M bottom-up). The analysis notes that closeness is not confirmation and that shared inputs may explain agreement, but it does not explain what drives the SAM gap specifically. The gap traces to different narrowing factors: the top-down approach uses a 55% SMB revenue share while the bottom-up uses a 65% serviceable establishment share \u2014 these measure different things (revenue concentration vs. addressable business count) and their divergence is not addressed. An investor will ask why SAM differs by nearly 20% between the two methods."
    },
    {
      "id": "growth_dynamics_considered",
      "category": "Methodology",
      "label": "Market growth dynamics considered",
      "status": "fail",
      "notes": "The analysis sizes the market on a current-year basis but does not record a CAGR or growth trend for the FSM software market. The sources consulted (P&S Intelligence's 2032 growth report and IBISWorld) typically publish CAGR data for this market \u2014 that figure was not captured. Including a market growth rate would allow investors to evaluate the opportunity as it will look at Series A or B, not just today, and is a standard expectation on any market sizing slide."
    },
    {
      "id": "market_properly_segmented",
      "category": "Market Understanding",
      "label": "Market properly segmented",
      "status": "pass",
      "notes": "The SAM is derived from specific segment criteria in both approaches. Top-down narrows by vertical (HVAC, plumbing, electrical) and then by company size (SMB revenue share). Bottom-up uses specific NAICS codes for the target trades, then filters by establishment size (2\u2013100 employees with multi-technician dispatch needs). The segmentation uses actual Census categories and published analyst breakdowns, not a hand-wavy percentage."
    },
    {
      "id": "competitive_landscape_acknowledged",
      "category": "Market Understanding",
      "label": "Competitive landscape acknowledged",
      "status": "not_applicable",
      "notes": "Cadence's materials were provided as a text description only \u2014 no pitch deck addressing competitive positioning was submitted. This item can only be scored from materials that discuss competition. It is skipped for want of materials; the market sizing narrative should address competitors (ServiceTitan, Jobber, Housecall Pro, Service Fusion) before investor presentations."
    },
    {
      "id": "sam_expansion_path_noted",
      "category": "Market Understanding",
      "label": "SAM expansion path noted",
      "status": "fail",
      "notes": "The analysis scopes SAM to HVAC, plumbing, and electrical contractors in the US with 1\u2013100 employees, but does not discuss how that addressable market could grow over time \u2014 through expansion to adjacent trades (landscaping, pest control, general contracting), geographic expansion beyond the US, or moving upmarket to larger enterprises. A SAM expansion path signals to investors that the initial beachhead is a starting point, not a ceiling."
    },
    {
      "id": "assumptions_explicit",
      "category": "Presentation",
      "label": "Assumptions explicit",
      "status": "pass",
      "notes": "Every key assumption is stated with its value, unit, source or derivation logic, and confidence category. An investor can identify and challenge any individual input: the vertical market share (27%, agent estimate), the SMB share (55%, single source), ARPU ($3,000/year, one pricing source), serviceable share (65%, agent estimate), and capture rates (3% and 2.5%, agent estimates) are all visible."
    },
    {
      "id": "formulas_shown",
      "category": "Presentation",
      "label": "Formulas shown",
      "status": "pass",
      "notes": "Every figure shows the formula behind it. Top-down: TAM = industry total; SAM = TAM \u00d7 segment share; SOM = SAM \u00d7 capture rate. Bottom-up: TAM = customer count \u00d7 ARPU; SAM = serviceable customers \u00d7 ARPU; SOM = target customers \u00d7 ARPU. The inputs to each formula are stated alongside the result."
    },
    {
      "id": "sources_cited",
      "category": "Presentation",
      "label": "Sources cited",
      "status": "pass",
      "notes": "Every external data point has a named source. The US FSM market total cites P&S Intelligence and IBISWorld (with URLs). Employer counts cite Census County Business Patterns via startbusinessbystate.com for NAICS 238220 (2023) and a secondary Census source for NAICS 238210 (2022). ARPU cites Software Advice. The FSM adoption rate and SMB share cite Fieldproxy. Agent estimates note they are estimates and give the reasoning used."
    }
  ],
  "summary": {
    "total": 22,
    "pass": 15,
    "fail": 4,
    "not_applicable": 3,
    "score_pct": 78.9,
    "overall_status": "solid",
    "all_pass": false,
    "failed_items": [
      {
        "id": "figures_triangulated",
